#include "room_test_resources.hpp"
#include "room_rules_internal.hpp"
#include "room_json.hpp"
#include <iostream>
using namespace wot::room;
int main(){std::string line;while(std::getline(std::cin,line)){try{const auto input=parseJson(line);State state;state.round_id=1;state.authority_epoch=1;state.phase="battle";state.map_name="04_himmelsdorf";state.server_tick=intField(input,"tick",301);state.server_time_ms=intField(input,"time",10000);state.monotonic_seconds=input.get("monotonic").numeric(100.);state.config=input.get("config");if(state.config.kind!=Value::Kind::Object)state.config=object();state.config.object["receipt_namespace"]=text("test-room");state.config.object["receipt_arena_prefix"]=integer(1);state.config.object["round_start_time"]=integer(123);const auto resource_data=rule::isObject(input.get("resources"))?input.get("resources"):object();state.resources=testResources(resource_data);for(const auto&a:rows(input.get("players")))state.players[intField(a,"id",intField(a,"player_id"))]=a;for(const auto&a:rows(input.get("bots")))state.bots[intField(a,"id")]=a;state.bot_manifest=input.get("manifest");Rules rules(state);rules.reset();bool store_ok=true;Value persistence=array();rules.receiptStore([&](const Value&next){persistence.array.push_back(next);return store_ok;});if(has(input,"restore_receipts"))rules.restoreReceipts(borrowedResourceTree(input.get("restore_receipts"),true));if(input.get("initialize").truth())for(const auto&row:state.players)rules.initializeActor("player",row.first);if(input.get("profiles").kind==Value::Kind::Array){const auto profile_result=rules.installHumanProfiles(input.get("profiles"));if(profile_result.status!=Outcome::Status::accepted)throw std::invalid_argument(profile_result.detail);}Value outcomes=array();for(const auto&op:rows(input.get("operations"))){const auto kind=op.get("op").resolved().text;if(kind=="store"){store_ok=op.get("okay").truth();}else if(kind=="inventory"||kind=="burst_edges"){Value item=object();try{if(kind=="store"){store_ok=op.get("okay").truth();}else if(kind=="inventory")rule::validateBotInventory(op.get("previous"),op.get("current"),op.get("unavailable").truth());else item.object["edges"]=rule::botBurstEdges(op.get("previous"),op.get("current"));item.object["valid"]=boolean(true);}catch(const std::exception&){item.object["valid"]=boolean(false);}outcomes.array.push_back(std::move(item));}else if(kind=="push"){rules.consumeEnvironmentPush(op.get("event"));}else if(kind=="disconnect"){const auto id=intField(op,"id");rules.playerDisconnected(id);state.players.erase(id);}else if(kind=="leave"){rules.playerLeftBattle(intField(op,"id"),op.get("voluntary").truth(true));}else if(kind=="observe"){state.player_spotted.clear();state.bot_spotted.clear();for(const auto&contact:rows(op.get("message").get("contacts"))){const Rules::ActorKey target{contact.get("target_kind").text=="human"?"player":"bot",intField(contact,"target_id")};for(const auto&id:rows(contact.get("visible_by_player_ids")))state.player_spotted[*exactInteger(id)].insert(target);for(const auto&id:rows(contact.get("visible_by_bot_ids")))state.bot_spotted[*exactInteger(id)].insert(target);}rules.observeVisibility(op.get("message"));}else if(kind=="advance"){state.server_tick=intField(op,"tick",state.server_tick+1);state.server_time_ms=intField(op,"time",state.server_time_ms+33);rules.advance(op.get("dt").numeric(1./30.));}else if(kind=="actor"){const auto actor_kind=op.get("kind").resolved().text;const auto id=intField(op,"id");auto*actor=state.actor(actor_kind,id);state.motion_time_us=intField(op,"motion_time_us",state.motion_time_us);const auto before=actor?*actor:Value{};for(const auto&kv:op.get("changes").resolved().object)actor->object[kv.first]=kv.second;rules.actorAdvanced(actor_kind,id,before,op.get("publication"));}else if(kind=="finish"){outcomes.array.push_back(boolean(rules.finish(static_cast<int>(intField(op,"winner")),op.get("reason").resolved().text,0,!has(op,"record_receipts")||op.get("record_receipts").truth())));}else{const auto result=kind=="checkpoint"?rules.checkpoint(op.get("message")):rules.dispatch({intField(op,"sender",-1),op.get("worker").truth()},op.get("message"));Value row=object();row.object["status"]=integer(static_cast<std::int64_t>(result.status));row.object["code"]=text(result.code);row.object["detail"]=text(result.detail);row.object["replies"]=array();row.object["replies"].array=result.replies;outcomes.array.push_back(std::move(row));}}
 Value output=object();output.object["outcomes"]=outcomes;output.object["persistence"]=persistence;output.object["projectiles"]=rules.projectiles();output.object["human_ram_probes"]=rules.humanRamProbes();output.object["rules"]=state.rules;output.object["battle_result"]=state.battle_result;output.object["events"]=array();output.object["events"].array=state.events;output.object["players"]=array();output.object["bots"]=array();output.object["statistics"]=object();for(const auto&actor:state.players){output.object["players"].array.push_back(actor.second);output.object["statistics"].object["player:"+std::to_string(actor.first)]=rules.statistics({"player",actor.first});}for(const auto&actor:state.bots){output.object["bots"].array.push_back(actor.second);output.object["statistics"].object["bot:"+std::to_string(actor.first)]=rules.statistics({"bot",actor.first});}output.object["receipts"]=rules.pendingReceipts("account");std::cout<<writeJson(output)<<'\n';}catch(const std::exception&e){Value error=object();error.object["error"]=text(e.what());std::cout<<writeJson(error)<<'\n';}}}
